CREATE TABLE mkt.trades (storage_key text PRIMARY KEY,document jsonb NOT NULL,immutable boolean NOT NULL DEFAULT false,"instrument_id" text,"trade_id" text,"token_id" text,"ts" timestamptz,"received_ts" timestamptz);
CREATE INDEX mkt_trades_instrument_id_idx ON mkt.trades("instrument_id");
CREATE INDEX mkt_trades_trade_id_idx ON mkt.trades("trade_id");
CREATE INDEX mkt_trades_token_id_idx ON mkt.trades("token_id");
CREATE INDEX mkt_trades_ts_idx ON mkt.trades("ts");
CREATE INDEX mkt_trades_received_ts_idx ON mkt.trades("received_ts");
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON mkt.trades FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
CREATE TABLE mkt.capture_gaps (storage_key text PRIMARY KEY,document jsonb NOT NULL,immutable boolean NOT NULL DEFAULT false,"gap_id" text,"instrument_id" text,"token_id" text,"start" timestamptz,"end" timestamptz,"kind" text,"reason" text,"observed_at" timestamptz);
CREATE INDEX mkt_capture_gaps_gap_id_idx ON mkt.capture_gaps("gap_id");
CREATE INDEX mkt_capture_gaps_instrument_id_idx ON mkt.capture_gaps("instrument_id");
CREATE INDEX mkt_capture_gaps_token_id_idx ON mkt.capture_gaps("token_id");
CREATE INDEX mkt_capture_gaps_start_idx ON mkt.capture_gaps("start");
CREATE INDEX mkt_capture_gaps_end_idx ON mkt.capture_gaps("end");
CREATE INDEX mkt_capture_gaps_kind_idx ON mkt.capture_gaps("kind");
CREATE INDEX mkt_capture_gaps_reason_idx ON mkt.capture_gaps("reason");
CREATE INDEX mkt_capture_gaps_observed_at_idx ON mkt.capture_gaps("observed_at");
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON mkt.capture_gaps FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
CREATE TABLE mkt.raw_archives (storage_key text PRIMARY KEY,document jsonb NOT NULL,immutable boolean NOT NULL DEFAULT false,"archive_id" text,"instrument_id" text,"kind" text,"path" text,"sha256" text,"received_ts" timestamptz);
CREATE INDEX mkt_raw_archives_archive_id_idx ON mkt.raw_archives("archive_id");
CREATE INDEX mkt_raw_archives_instrument_id_idx ON mkt.raw_archives("instrument_id");
CREATE INDEX mkt_raw_archives_kind_idx ON mkt.raw_archives("kind");
CREATE INDEX mkt_raw_archives_path_idx ON mkt.raw_archives("path");
CREATE INDEX mkt_raw_archives_sha256_idx ON mkt.raw_archives("sha256");
CREATE INDEX mkt_raw_archives_received_ts_idx ON mkt.raw_archives("received_ts");
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON mkt.raw_archives FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
CREATE TABLE mkt.capture_state (storage_key text PRIMARY KEY,document jsonb NOT NULL,immutable boolean NOT NULL DEFAULT false,"instrument_id" text,"last_trade_id" text,"last_ts" timestamptz,"updated_at" timestamptz);
CREATE INDEX mkt_capture_state_instrument_id_idx ON mkt.capture_state("instrument_id");
CREATE INDEX mkt_capture_state_last_trade_id_idx ON mkt.capture_state("last_trade_id");
CREATE INDEX mkt_capture_state_last_ts_idx ON mkt.capture_state("last_ts");
CREATE INDEX mkt_capture_state_updated_at_idx ON mkt.capture_state("updated_at");
CREATE TRIGGER immutable_record BEFORE UPDATE OR DELETE ON mkt.capture_state FOR EACH ROW EXECUTE FUNCTION ops.protect_immutable();
CREATE UNIQUE INDEX mkt_trades_natural ON mkt.trades(instrument_id,trade_id);